document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('newPlaylist').onclick=newPlaylist;$('privacy').onclick=info;$('profile').onclick=info;$('stopVideo').onclick=stopYouTube;$('playerLike').onclick=()=>toggleLike(current);
$('play').onclick=async()=>{if(current===null){playTrack(6);return;}if(isYouTube()){if(!ytReady){toast('Use the YouTube player once it loads.');return;}$('watchZone').scrollIntoView({behavior:'smooth',block:'start'});videoVisible=true;youtube.getPlayerState()===1?youtube.pauseVideo():youtube.playVideo();return;}if(audio.paused){try{await audio.play();}catch{toast('Unable to play audio.');}}else audio.pause();};
$('next').onclick=()=>next();$('prev').onclick=()=>{if(isYouTube()){if(ytReady&&youtube.getCurrentTime()>3)youtube.seekTo(0,true);else next(-1);}else if(audio.currentTime>3)audio.currentTime=0;else next(-1);};
$('shuffle').onclick=()=>{shuffle=!shuffle;$('shuffle').setAttribute('aria-pressed',String(shuffle));$('shuffle').classList.toggle('liked',shuffle);if(isYouTube()&&track(current).source==='youtube-playlist'&&ytReady)youtube.setShuffle(shuffle);toast(shuffle?'Shuffle on':'Shuffle off');};
$('repeat').onclick=()=>{repeat=!repeat;audio.loop=repeat;if(isYouTube()&&track(current).source==='youtube-playlist'&&ytReady)youtube.setLoop(repeat);$('repeat').setAttribute('aria-pressed',String(repeat));$('repeat').classList.toggle('liked',repeat);toast(repeat?'Repeat on':'Repeat off');};
$('queueToggle').onclick=$('headerQueue').onclick=()=>{if(isYouTube()&&ytReady)youtube.pauseVideo();$('queuePanel').hidden=!$('queuePanel').hidden;};$('closeQueue').onclick=()=>{$('queuePanel').hidden=true;};
$('volume').oninput=()=>{audio.volume=Number($('volume').value);if(ytReady)youtube.setVolume(Number($('volume').value)*100);};
$('seek').oninput=()=>{if(isYouTube()){if(ytReady)youtube.seekTo(Number($('seek').value),true);}else if(current!==null&&Number.isFinite(audio.duration))audio.currentTime=Number($('seek').value);};
audio.onplay=()=>{if(!isYouTube())setPlayState(true);};audio.onpause=()=>{if(!isYouTube())setPlayState(false);};audio.ontimeupdate=()=>{if(isYouTube())return;$('seek').value=audio.currentTime;$('elapsed').textContent=time(audio.currentTime);};audio.onloadedmetadata=()=>{if(isYouTube())return;$('seek').max=audio.duration;$('duration').textContent=time(audio.duration);};audio.onended=()=>{if(!isYouTube())next();};audio.onerror=()=>{if(!isYouTube())toast('The demo audio could not load.');};
setInterval(()=>{if(isYouTube()&&ytReady){const duration=youtube.getDuration(),position=youtube.getCurrentTime();if(Number.isFinite(duration)&&duration>0){$('seek').max=duration;$('seek').value=position;$('elapsed').textContent=time(position);$('duration').textContent=time(duration);}}},500);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&isYouTube()&&ytReady)youtube.pauseVideo();});
if('IntersectionObserver' in window){new IntersectionObserver(entries=>{videoVisible=entries[0].intersectionRatio>=.75;if(!videoVisible&&isYouTube()&&ytReady&&youtube.getPlayerState()===1){youtube.pauseVideo();$('videoStatus').textContent='Paused — keep the YouTube player in view to listen.';}},{threshold:[0,.75,1]}).observe($('watchZone').querySelector('.video-frame'));}
renderNav();render();
